#include <bits/stdc++.h>
using namespace std;
void solve() {
	int n;
	long x;
	cin >> n >> x;
	vector<long> a(n);
	for (long &v : a) cin >> v;
	priority_queue<pair<long, long>> pq;
	pq.push({x + 1, 1});
	for (long v : a) {
		while (!pq.empty() && pq.top().first > v) {
			auto [val, cnt] = pq.top();
			pq.pop();
			while (!pq.empty() && pq.top().first == val) {
				cnt += pq.top().second;
				pq.pop();
			}
			pq.push({v, val / v * cnt});
			if (val % v != 0) pq.push({val % v, cnt});
		}
	}
	long ans = -1;
	while (!pq.empty()) {
		ans += pq.top().second;
		pq.pop();
	}
	cout << ans << '\n';
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin >> t;
	while (t--) solve();
}
